     /// <inheritdoc />
     public string DateHumanize_Never() => "never";

     /// <inheritdoc />
     public string TimeUnitHumanize(TimeUnit timeUnit, int count, bool toWords = false)
     {
         var unit = GetUnitName(timeUnit, count);
         return toWords ? $"{NumberToWords(count)} {unit}" : $"{count} {unit}";
     }

     private static string GetUnitName(TimeUnit timeUnit, int count)
     {
         return (timeUnit, count) switch
         {
             (TimeUnit.Year, 1) => "year",
             (TimeUnit.Year, _) => "years",
             (TimeUnit.Month, 1) => "month",
